import pandas as pd
import numpy as np

# Load data
data = pd.read_csv('getisord_2022_no2.csv')
adjacency_path = pd.read_csv('borough_adjacency.csv')

# Handle missing values
data['NO2_value'] = data['NO2_value'].fillna(data['NO2_value'].mean())

# Get unique boroughs
boroughs = data['borough'].unique()

# Create a dictionary to store the number of neighbors for each borough
neighbor_count = {}
for i, row in adjacency_path.iterrows():
    if row['neighbor'] not in neighbor_count:
        neighbor_count[row['neighbor']] = 1
    else:
        neighbor_count[row['neighbor']] += 1

# Create a dictionary to store the neighbors for each borough
neighbors = {}
for i, row in adjacency_path.iterrows():
    if row['neighbor'] not in neighbors:
        neighbors[row['neighbor']] = [row['borough']]
    else:
        neighbors[row['neighbor']].append(row['borough'])

# Create a dictionary to store the combined NO2 values for each borough
combined_no2 = {}
for borough in boroughs:
    combined_no2[borough] = data[data['borough'] == borough]['NO2_value'].sum()

# Create a dictionary to store the citywide average NO2 value
citywide_average = data['NO2_value'].mean()

# Create a dictionary to store the Getis-Ord Gi* values for each borough
gi_values = {}
for borough in boroughs:
    numerator = combined_no2[borough] - citywide_average
    denominator = citywide_average * np.sqrt(1 + (1 / neighbor_count[borough]))
    gi_values[borough] = numerator / denominator

# Identify statistically significant hot and cold spots
hot_spots = []
cold_spots = []
for borough, value in gi_values.items():
    if abs(value) > 1.96:
        if value > 0:
            hot_spots.append((borough, value))
        else:
            cold_spots.append((borough, value))

# Print final answer
data_points_used = len(boroughs) - data['NO2_value'].isnull().sum()
print(f'data_points_used = {data_points_used}')
if hot_spots or cold_spots:
    results = []
    for hot in hot_spots:
        results.append(f'{hot[0]} (HOT, Gi*={hot[1]}, gi_value={hot[1]})')
    for cold in cold_spots:
        results.append(f'{cold[0]} (COLD, Gi*={cold[1]}, gi_value={cold[1]})')
    print(f'FINAL ANSWER: {", ".join(results)}')
else:
    print('FINAL ANSWER: none')

