import pandas as pd
import numpy as np

# Load the data into a pandas DataFrame
data = pd.read_csv('chunks_csv/getisord/getisord_2022_no2.csv')
adjacency = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Handle missing values by dropping rows with missing NO2 values
data = data.dropna(subset=['NO2_value'])

# Create a dictionary to store the neighboring boroughs for each borough
neighborhoods = {}
for index, row in adjacency.iterrows():
    if row['borough'] not in neighborhoods:
        neighborhoods[row['borough']] = []
    neighborhoods[row['borough']].append(row['neighbor'])

# Calculate the total NO2 value for each borough and its neighbors
neighborhoods_data = {}
for borough, neighbors in neighborhoods.items():
    neighborhoods_data[borough] = data[data['borough'].isin(neighbors + [borough])]['NO2_value'].sum()

# Calculate the citywide average NO2 value
citywide_average = data['NO2_value'].mean()

# Use the Getis-Ord Gi* method to calculate the Gi* statistic for each borough
gi_values = {}
for borough, total_no2 in neighborhoods_data.items():
    gi_values[borough] = (total_no2 - citywide_average * (1 + len(neighborhoods[borough]))) / np.sqrt(citywide_average * (1 - citywide_average) * (1 + len(neighborhoods[borough]) * (1 - 1 / (len(data) - 1))))

# Identify boroughs with a statistically significant Gi* value
significant_boroughs = {}
for borough, gi in gi_values.items():
    if np.abs(gi) > 1.96:  # 95% confidence
        significant_boroughs[borough] = gi
    elif np.abs(gi) > 2.576:  # 99% confidence
        significant_boroughs[borough] = gi

# Store the results in a list of tuples
results = []
for borough, gi in significant_boroughs.items():
    if gi > 0:
        results.append((borough, 'HOT', gi))
    else:
        results.append((borough, 'COLD', gi))

# Print the results in the required format
print(f"data_points_used = {len(data)}")
if results:
    print(f"FINAL ANSWER: {', '.join(f'{borough} ({spot_type}, Gi*={gi}, gi_value={gi})' for borough, spot_type, gi in results)}")
else:
    print("FINAL ANSWER: none")
